// Simplified Chinese copy (zh-CN, 简体中文). Natural, warm Mainland-Chinese wording for a women's health application,
// NOT a literal word-for-word rendering of en.ts. Same key set and the same interpolation placeholders as the other
// dictionaries. Chinese has no grammatical plural (CLDR category "other" only): every _one/_other pair therefore
// carries the same wording, kept only so the key set stays identical to en.ts.
//
// Conventions: second person «你» (not the honorific 您 in running text), full-width punctuation （，。？！：；“”‘’）,
// no space between Chinese and digits/Latin words except around product names; «AWA» and «PDF/CSV/JSON/PIN/Face ID»
// stay Latin; the product title is «AWA 高级版»; the typed destructive-confirmation word is «删除»; the partner
// feature is «AWA 同行»; language names are endonyms («简体中文»). Medical terms use the standard mainland
// terminology (月经, 月经周期, 排卵, 易孕期, 怀孕, 产后, 多囊卵巢综合征, 围绝经期). Religious-practice terms use the common
// Chinese transliterations (礼拜, 斋戒, 补斋 Qada, 产后恶露期 Nifas, 伊斯提哈达 Istihada) and stay neutral and
// educational; the wording still needs scholar validation, exactly as in the other languages. Not reviewed by a
// native medical translator.
